// Islam Makhachev's real voice lines (Joe's recordings, 2026-11-22), played
// from his specials (islam-specials.js) through the talk channel only
// (CLAUDE.md: cutInTalk, a special's own call). Source cuts are saved in
// project-files/sound/islam/.
//   islamBrotha      "Brotha" (soundinstants button)            Brotha
//   islamCheesecake  "California cheesecake, yes" (TikTok)     California Cheesecake
//   islamDagestan    "2-3 years Dagestan" (myinstants button)  2-3 years Dagestan
//   islamKangaroo    "I know kangaroo have good striking, but nobody check the
//                    grappling" (FightForce short)              Volk's kangaroo
"use strict";
if (typeof SOUND_CLIPS !== "undefined") {
  SOUND_CLIPS.islamBrotha = "data:audio/mpeg;base64,";
  SOUND_CLIPS.islamCheesecake = "data:audio/mpeg;base64,";
  SOUND_CLIPS.islamDagestan = "data:audio/mpeg;base64,";
  SOUND_CLIPS.islamKangaroo = "data:audio/mpeg;base64,";
}
var ISLAM_VOICE = ["islamBrotha", "islamCheesecake", "islamDagestan", "islamKangaroo"];
var islamVoiceWarmed = false;
// From updateIslamMoves (islam-axe.js), every frame on Islam: decode his lines
// ahead of time so they're ready when a special starts.
function islamVoiceWarm() {
  if (islamVoiceWarmed || typeof withClip !== "function" || !audioCtx) return;
  islamVoiceWarmed = true;
  ISLAM_VOICE.forEach(function (n) { withClip(n); });
}
// Plays one of his lines, cutting in (it's the special's own call). If it
// isn't decoded yet it plays as soon as it is, while `still()` holds.
function islamVoice(name, still) {
  if (typeof cutInTalk !== "function" || !audioCtx) return;
  if (clipBuffers[name]) { cutInTalk(name, 1); return; }
  withClip(name, function () { if (!still || still()) cutInTalk(name, 1); });
}
